-- ═══════════════════════════════════════════════════════════════════════════
-- Realtime (safe to re-run)
-- ═══════════════════════════════════════════════════════════════════════════

do $$
declare
  t text;
begin
  foreach t in array array[
    'recipes', 'meal_assignments', 'eaten', 'water',
    'recipe_notes', 'shopping_checks', 'pantry', 'menus', 'households', 'profiles',
    'day_sections', 'labels'
  ] loop
    begin
      execute format('alter publication supabase_realtime add table public.%I', t);
    exception
      when duplicate_object then null;
      when undefined_object then null;
    end;
  end loop;
end $$;


-- Step 3 — the preset recipe + day-menu library
-- ═══════════════════════════════════════════════════════════════════════════
-- Our Table — shared vegetarian recipe library (generated)
-- Generated by scripts/generate-seed.mjs — do not edit by hand.
-- These rows have household_id = NULL and are read-only in the app.
-- ═══════════════════════════════════════════════════════════════════════════

insert into public.recipes (
  id, household_id, name_en, name_lt, emoji, slot, kcal, protein, carbs, fat,
  ingredients, method_en, method_lt, tags, vegetarian, prep_minutes
) values
(
