  '[{"key":"natural-tofu","en":"Natural tofu","lt":"Natūralus tofu","amount":150,"unit":"g"},{"key":"black-olives","en":"Black olives","lt":"Juodos alyvuogės","amount":40,"unit":"g"},{"key":"tomato","en":"Tomato","lt":"Pomidoras","amount":100,"unit":"g"},{"key":"cucumber","en":"Cucumber","lt":"Agurkas","amount":100,"unit":"g"},{"key":"spinach","en":"Spinach","lt":"Špinatai","amount":25,"unit":"g"},{"key":"iceberg-lettuce","en":"Iceberg lettuce","lt":"Aisbergo salotos","amount":25,"unit":"g"},{"key":"pumpkin-seeds","en":"Pumpkin seeds","lt":"Moliūgų sėklos","amount":10,"unit":"g"},{"key":"olive-oil","en":"Olive oil","lt":"Alyvuogių aliejus","amount":15,"unit":"g"}]'::jsonb,
  'Dice tofu and fry in pan with a little oil. Splash with GF soy sauce at the end. Prepare salad from tomato, cucumber, spinach and iceberg. Dress with 1 tsp olive oil, a little vinegar, salt and herbs. Top with tofu, black olives and pumpkin seeds.',
  'Tofu supjaustyti kubeliais ir pakepinti su a.š. aliejaus, baigiant apšlakstyti sojos padažu. Iš pomidorų, agurko, špinatų ir aisbergo paruošti salotas, pagardinti aliejumi, actu, druska, žolelėmis. Ant viršaus uždėti tofu, alyvuoges ir sėklas.',
  array['vegetarian', 'low-fodmap', 'gluten-free', 'dairy-free', 'vegan']::text[],
  true,
  20
)
on conflict (id) do update set
  name_en = excluded.name_en,
  name_lt = excluded.name_lt,
  emoji = excluded.emoji,
  slot = excluded.slot,
  kcal = excluded.kcal,
  protein = excluded.protein,
  carbs = excluded.carbs,
  fat = excluded.fat,
  ingredients = excluded.ingredients,
  method_en = excluded.method_en,
  method_lt = excluded.method_lt,
  tags = excluded.tags,
  prep_minutes = excluded.prep_minutes,
  updated_at = now()
where recipes.household_id is null;

